import { test, expect } from '../../fixtures';
import { EDIT_LEAD_NAME, ROLE, city, clearAddress, openEditLead, region, typeAndPickSuggestion, zip } from './lead-address-helpers';
import { pp } from '../pricebook/pricebook-helpers';

test.describe('Адрес: City из подсказки — город, не район (#dad444)', () => {
  test('Edit Lead: changing the address to "400 Broad St, Seattle" fills City = Seattle #dad444 @desktop @google-places', async ({ asUser }) => {
    const page = await asUser(ROLE);
    await openEditLead(page, EDIT_LEAD_NAME);
    await clearAddress(page);

    await typeAndPickSuggestion(page, '400 Broad St Seattle', '400 Broad St', 'Seattle, WA, USA');

    await expect(zip(page)).toHaveValue('98109');
    // источник: «מה רצוי» #dad444; коммент программиста — New Lead и Edit Lead
    await expect(city(page)).toHaveValue('Seattle');
    await expect(region(page)).toHaveValue('Washington');

    // Без сохранения
    await page.goto(pp('/Leads'));
    await expect(page.getByPlaceholder('Search leads...')).toBeVisible();
  });
});
